result.text:
      seedDemo();
      toast("Datos de ejemplo cargados.");
      render();
      return;
    }
    case "retry-job": {
      const job = ui.jobs.find((j) => j.id === id);
      if (job) {
        job.state = "queued";
        job.pct = 0;
        job.error = "";
        paintIngest();
        runQueue();
      }
      return;
    }
    case "acc-tab": {
      ui.conta.tab = id || "diario";
      render();
      return;
    }
    case "acc-apertura":
    case "acc-settings": {
      accAperturaModal();
      return;
    }
    case "acc-save-apertura": {
      saveApertura();
      return;
    }
    case "export-acc-csv": {
      exportAccCsv();
      return;
    }
    default:
      return;
  }
}

